scenes.setup:
const { api } = await import('./js/api.js');
const sources = await api.live();
let entry = { id: sources[0].id, state: 'paused', score: [0, 0] };
api.startGame = async () => entry;
api.gameStream = (id, signal) => api.liveStream(id, signal);
api.pauseGame = async (id, paused) => { entry = { ...entry, state: paused ? 'paused' : 'playing' }; return entry; };
api.gameInput = async () => entry;
api.game = async () => entry;
await cuju.play.start();
for (let i = 0; i < 100 && !cuju.play.game.started; i++) await new Promise((r) => setTimeout(r, 100));
cuju.play.lastDevice = 'Controller';
cuju.play.toggleCard(true);
const k = cuju.source.header.players.findIndex((p) => p.team === 0 && p.index === 9);
const mark = () => { const st = cuju.timeline.store; for (let i = Math.max(st.first, st.last - 60); i <= st.last; i++) { const f = st.get(i); if (f) f.playerFlags[k] |= 8; } };
mark(); setInterval(() => { mark(); promo.hideNumbers(cuju.play.stage); }, 40);
